20	// 资金库状态文件相关错误。
21	var (
22		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
23		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
24		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
25		ErrStateCorrupt = errors.New("treasury state file is corrupt")
26		// ErrProposalNotFound：按编号查询或执行时提案不存在。
27		ErrProposalNotFound = errors.New("proposal not found")
28		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
29		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
30		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
31		ErrInvalidRegistration = errors.New("invalid registration")
32	)
33	
34	const (
35		stateMagic   = "govflow-treasury-state"
36		stateVersion = 1
37		lockSuffix   = ".lock"
38	)
39	
40	// BalanceUpdate 记录一个账户在一次动作前后的余额。
41	//
42	// before 与 after 必须各自明确写出且为 int64 整数：字段缺失、为 null 或
43	// 类型不符都不得被折叠成 0 再当作合法凭据读出——某个余额本来应为 0 时，
44	// 缺失字段与明确写出的 0 在解码后必须仍可区分。因此解码时保留字段的原始
45	// JSON，由 validateReceiptActionBalances 区分“缺失/空值/类型不符”。
46	type BalanceUpdate struct {
47		Account string `json:"account"`
48		Before  int64  `json:"before"`
49		After   int64  `json:"after"`
50	
51		beforeRaw json.RawMessage
52		afterRaw  json.RawMessage
53	}
54	
55	// balanceUpdateJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
56	type balanceUpdateJSONShape struct {
57		Account string          `json:"account"`
58		Before  json.RawMessage `json:"before"`
59		After   json.RawMessage `json:"after"`
60	}
61	
62	// UnmarshalJSON 保留 before/after 是否出现及其原始写法（缺失为 nil、null 为
63	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
64	// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给
65	// validateReceiptActionBalances，此处只在字段确实是 int64 整数时填充值。
66	func (u *BalanceUpdate) UnmarshalJSON(data []byte) error {
67		var shape balanceUpdateJSONShape
68		if err := json.Unmarshal(data, &shape); err != nil {
69			return err
70		}
71		u.Account = shape.Account
72		u.beforeRaw, u.afterRaw = shape.Before, shape.After
73		fillInt64(shape.Before, &u.Before)
74		fillInt64(shape.After, &u.After)
75		return nil
76	}
77	
78	// mustBalanceUpdate 构造一份内存中的合法余额记录（首次执行构造凭据使用）。
79	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
80	// validateReceiptActionBalances 判定时不会把本进程新建的凭据误判为字段缺失。
81	func mustBalanceUpdate(account string, before, after int64) BalanceUpdate {
82		beforeRaw, _ := json.Marshal(before)
83		afterRaw, _ := json.Marshal(after)
84		return BalanceUpdate{
85			Account: account, Before: before, After: after,
86			beforeRaw: beforeRaw, afterRaw: afterRaw,
87		}
88	}
89	
90	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
91	// 以及该动作引发的资金库与收款账户余额变动。两侧的 before/after 四个余额字段
92	// 都必须明确写出；任何一个缺失、为 null 或类型不符，整份状态文件即判损坏，
93	// 不能根据转账金额、账户余额或其它凭据补出（见 validateReceiptActionBalances）。
94	type ActionReceipt struct {
95		Index     int           `json:"index"`
96		Action    string        `json:"action"`
97		Treasury  BalanceUpdate `json:"treasury"`
98		Recipient BalanceUpdate `json:"recipient"`
99	}
100	
101	// Receipt 是一项提案首次成功执行后生成的执行凭据。
102	// 一项提案只允许成功一次；重试返回同一份凭据。
103	//
104	// executed_at 必须明确写出且不得早于对应提案的 timelock_end：首次执行只在
105	// now 达到时间锁后发生，保存的凭据必须满足同一条执行资格规则。字段缺失、
106	// 为 null 或类型不符都不得被折叠成 0 再当作合法凭据读出，因此解码时保留
107	// 字段的原始 JSON，由 validateState 区分“缺失/空值/类型不符/早于时间锁”。
108	type Receipt struct {
109		ProposalID string          `json:"proposal_id"`
110		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
111		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
112		Actions    []ActionReceipt `json:"actions"`
113	
114		executedAtRaw json.RawMessage
115	}
116	
117	// receiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
118	type receiptJSONShape struct {
119		ProposalID string          `json:"proposal_id"`
120		ExecutedAt json.RawMessage `json:"executed_at"`
121		Order      int             `json:"order"`
122		Actions    []ActionReceipt `json:"actions"`
123	}
124	
125	// UnmarshalJSON 保留 executed_at 是否出现及其原始写法（缺失为 nil、null 为
126	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
127	// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给 validateState，
128	// 此处只在字段确实是 int64 整数时填充 ExecutedAt。
129	func (r *Receipt) UnmarshalJSON(data []byte) error {
130		var shape receiptJSONShape
131		if err := json.Unmarshal(data, &shape); err != nil {
132			return err
133		}
134		r.ProposalID = shape.ProposalID
135		r.Order = shape.Order
136		r.Actions = shape.Actions
137		r.executedAtRaw = shape.ExecutedAt
138		fillInt64(shape.ExecutedAt, &r.ExecutedAt)
139		return nil
140	}
141	
142	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
143	type ProposalRecord struct {
144		ID          string   `json:"id"`
145		State       string   `json:"state"`
146		TimelockEnd int64    `json:"timelock_end"`
147		Actions     []string `json:"actions"`
148	}
149	
150	// ---- 磁盘结构（JSON） ----
151	
152	type storedProposal struct {
153		ID          string   `json:"id"`
154		State       string   `json:"state"`
155		TimelockEnd int64    `json:"timelock_end"`
156		Actions     []string `json:"actions"`
157	}
158	
159	type storedState struct {
160		Magic           string                         `json:"magic"`
161		Version         int                            `json:"version"`
162		InitialTreasury int64                          `json:"initial_treasury"`
163		Treasury        int64                          `json:"treasury"`
164		Balances        map[string]int64               `json:"balances"`
165		Proposals       map[string]*storedProposal     `json:"proposals"`
166		Receipts        []*Receipt                     `json:"receipts"`
167		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
168	}
169	
170	// Store 是绑定到单个本地状态文件的资金库句柄。
171	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
172	// 通过进程内互斥锁与文件锁（flock）串行化。
173	type Store struct {
174		path   string
175		mu     sync.Mutex // 保护本句柄上的全部操作
176		lockFD *os.File   // 跨进程文件锁
177		closed bool
178	}
179	
180	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
181	var (
182		pathLocksMu sync.Mutex
183		pathLocks   = map[string]*sync.Mutex{}
184	)
185	
186	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
187	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
188	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
189	func canonicalPath(path string) (string, error) {
190		return filepath.Abs(path)
191	}
192	
193	func inProcessLock(path string) *sync.Mutex {
194		pathLocksMu.Lock()
195		defer pathLocksMu.Unlock()
196		m, ok := pathLocks[path]
197		if !ok {
198			m = &sync.Mutex{}
199			pathLocks[path] = m
200		}
201		return m
202	}
203	
204	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
205	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
206	// treasury 必须落在有符号 64 位整数范围内且不得为负。
207	func InitTreasury(path string, treasury int64) (*Store, error) {
208		if treasury < 0 {
209			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
210		}
211		path, err := canonicalPath(path)
212		if err != nil {
213			return nil, err
214		}
215		pathMu := inProcessLock(path)
216		pathMu.Lock()
217		defer pathMu.Unlock()
218	
219		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
220		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
221		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
222		if err != nil {
223			return nil, err
224		}
225		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
226			_ = lockFD.Close()
227			return nil, err
228		}
229		// O_EXCL 保证与并发初始化竞争时只有一方成功。
230		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
231		if err != nil {
232			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
233			_ = lockFD.Close()
234			if errors.Is(err, fs.ErrExist) {
235				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
236			}
237			return nil, err
238		}
239		_ = fd.Close()
240	
241		store := &Store{path: path, lockFD: lockFD}
242		if err := store.commitLocked(newStoredState(treasury)); err != nil {
243			_ = store.funlock()
244			_ = lockFD.Close()
245			_ = os.Remove(path)
246			return nil, err
247		}
248		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
249		if err := store.funlock(); err != nil {
250			_ = lockFD.Close()
251			_ = os.Remove(path)
252			return nil, err
253		}
254		return store, nil
255	}
256	
257	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
258	func Open(path string) (*Store, error) {
259		path, err := canonicalPath(path)
260		if err != nil {
261			return nil, err
262		}
263		pathMu := inProcessLock(path)
264		pathMu.Lock()
265		defer pathMu.Unlock()
266		return openStoreHoldingPathLock(path)
267	}
268	
269	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
270	func openStoreHoldingPathLock(path string) (*Store, error) {
271		if _, err := os.Stat(path); err != nil {
272			return nil, err
273		}
274		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
275		if err != nil {
276			return nil, err
277		}
278		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
279			_ = lockFD.Close()
280			return nil, err
281		}
282		store := &Store{path: path, lockFD: lockFD}
283		if _, err := store.loadLocked(); err != nil {
284			_ = store.funlock()
285			_ = lockFD.Close()
286			return nil, err
287		}
288		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
289		if err := store.funlock(); err != nil {
290			_ = lockFD.Close()
291			return nil, err
292		}
293		return store, nil
294	}
295	
296	// Path 返回状态文件路径。
297	func (s *Store) Path() string { return s.path }
298	
299	// Close 释放文件锁。关闭后其它操作返回错误。
300	func (s *Store) Close() error {
301		s.mu.Lock()
302		defer s.mu.Unlock()
303		if s.closed {
304			return nil
305		}
306		s.closed = true
307		if err := s.funlock(); err != nil {
308			_ = s.lockFD.Close()
309			return err
310		}
311		return s.lockFD.Close()
312	}
313	
314	func (s *Store) flock(how int) error {
315		if s.lockFD == nil {
316			return errors.New("treasury store is closed")
317		}
318		return syscall.Flock(int(s.lockFD.Fd()), how)
319	}
320	
321	func (s *Store) funlock() error {
322		if s.lockFD == nil {
323			return nil
324		}
325		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
326	}
327	
328	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
329	// 返回的 commit 在操作结束时释放锁。
330	func (s *Store) begin() (func(), error) {
331		pathMu := inProcessLock(s.path)
332		pathMu.Lock()
333		s.mu.Lock()
334		if s.closed {
335			s.mu.Unlock()
336			pathMu.Unlock()
337			return nil, errors.New("treasury store is closed")
338		}
339		if err := s.flock(syscall.LOCK_EX); err != nil {
340			s.mu.Unlock()
341			pathMu.Unlock()
342			return nil, err
343		}
344		return func() {
345			_ = s.funlock()
346			s.mu.Unlock()
347			pathMu.Unlock()
348		}, nil
349	}
350	
351	func newStoredState(treasury int64) *storedState {
352		return &storedState{
353			Magic:           stateMagic,
354			Version:         stateVersion,
355			InitialTreasury: treasury,
356			Treasury:        treasury,
357			Balances:        map[string]int64{},
358			Proposals:       map[string]*storedProposal{},
359			Receipts:        []*Receipt{},
360			VoteProposals:   map[string]*storedVoteProposal{},
361		}
362	}
363	
364	// ---- 登记 ----
365	
366	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
367	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
368	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
369	// 内容不同则返回 ErrProposalConflict。
370	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
371		if id == "" {
372			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
373		}
374		commit, err := s.begin()
375		if err != nil {
376			return false, err
377		}
378		defer commit()
379	
380		state, err := s.loadLocked()
381		if err != nil {
382			return false, err
383		}
384		stored := copyActions(actions)
385		if existing, ok := state.Proposals[id]; ok {
386			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
387				return true, nil
388			}
389			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
390		}
391		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
392		if vp, ok := state.VoteProposals[id]; ok {
393			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
394		}
395		state.Proposals[id] = &storedProposal{
396			ID:          id,
397			State:       "passed",
398			TimelockEnd: timelockEnd,
399			Actions:     stored,
400		}
401		if err := s.commitLocked(state); err != nil {
402			return false, err
403		}
404		return false, nil
405	}
406	
407	func copyActions(actions []string) []string {
408		if actions == nil {
409			return nil
410		}
411		copied := make([]string, len(actions))
412		copy(copied, actions)
413		return copied
414	}
415	
416	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
417	func sameActions(a, b []string) bool {
418		if len(a) != len(b) {
419			return false
420		}
421		for i := range a {
422			if a[i] != b[i] {
423				return false
424			}
425		}
426		return true
427	}
428	
429	// ---- 执行 ----
430	
431	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
432	type executionTarget struct {
433		state        string
434		timelockEnd  int64
435		actions      []string
436		markExecuted func()
437	}
438	
439	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
440	func resolveExecutable(state *storedState, id string) *executionTarget {
441		if p, ok := state.Proposals[id]; ok {
442			return &executionTarget{
443				state:        p.State,
444				timelockEnd:  p.TimelockEnd,
445				actions:      p.Actions,
446				markExecuted: func() { p.State = "executed" },
447			}
448		}
449		if vp, ok := state.VoteProposals[id]; ok {
450			return &executionTarget{
451				state:        vp.State,
452				timelockEnd:  vp.TimelockEnd,
453				actions:      vp.Actions,
454				markExecuted: func() { vp.State = "executed" },
455			}
456		}
457		return nil
458	}
459	
460	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
461	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
462		if p, ok := state.Proposals[id]; ok {
463			return p.State, p.TimelockEnd, p.Actions, true
464		}
465		if vp, ok := state.VoteProposals[id]; ok {
466			return vp.State, vp.TimelockEnd, vp.Actions, true
467		}
468		return "", 0, nil, false
469	}
470	
471	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
472	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
473	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
474	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
475	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
476	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
477		commit, err := s.begin()
478		if err != nil {
479			return nil, err
480		}
481		defer commit()
482	
483		state, err := s.loadLocked()
484		if err != nil {
485			return nil, err
486		}
487		target := resolveExecutable(state, id)
488		if target == nil {
489			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
490		}
491		if target.state == "executed" {
492			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
493				return cloneReceipt(rcpt), nil
494			}
495			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
496		}
497		if target.state != "passed" {
498			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
499		}
500		if now < target.timelockEnd {
501			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
502		}
503		if len(target.actions) == 0 {
504			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
505		}
506	
507		// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
508		// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
509		steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
510		if perr != nil {
511			return nil, perr
512		}
513	
514		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
515		receipt := &Receipt{
516			ProposalID: id,
517			ExecutedAt: now,
518			Order:      len(state.Receipts),
519			Actions:    make([]ActionReceipt, 0, len(steps)),
520		}
521		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
522		// executed_at 判定时不会把本进程新建的凭据误判为字段缺失。
523		receipt.executedAtRaw, _ = json.Marshal(now)
524		for i, st := range steps {
525			receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
526		}
527		state.Treasury = simTreasury
528		state.Balances = simBalances
529		target.markExecuted()
530		state.Receipts = append(state.Receipts, receipt)
531	
532		if err := s.commitLocked(state); err != nil {
533			return nil, err
534		}
535		return cloneReceipt(receipt), nil
536	}
537	
538	func findReceipt(receipts []*Receipt, id string) *Receipt {
539		for _, r := range receipts {
540			if r.ProposalID == id {
541				return r
542			}
543		}
544		return nil
545	}
