547	func cloneReceipt(r *Receipt) *Receipt {
548		if r == nil {
549			return nil
550		}
551		copied := *r
552		if r.Actions != nil {
553			copied.Actions = make([]ActionReceipt, len(r.Actions))
554			copy(copied.Actions, r.Actions)
555		}
556		return &copied
557	}
