717	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
718	func (s *Store) loadLocked() (*storedState, error) {
719		raw, err := os.ReadFile(s.path)
720		if err != nil {
721			return nil, err
722		}
723		if len(bytes.TrimSpace(raw)) == 0 {
724			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
725		}
726		if err := checkStateStructure(raw); err != nil {
727			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
728		}
729		var state storedState
730		dec := json.NewDecoder(bytes.NewReader(raw))
731		dec.DisallowUnknownFields()
732		if err := dec.Decode(&state); err != nil {
733			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
734		}
735		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
736		var extra json.RawMessage
737		if err := dec.Decode(&extra); err != io.EOF {
738			if err == nil {
739				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
740			}
741			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
742		}
743		if err := validateState(&state); err != nil {
744			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
745		}
746		return &state, nil
747	}
748	
749	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
750	// 任一步失败都保留上次完整状态。调用方必须持锁。
751	func (s *Store) commitLocked(state *storedState) error {
752		if err := validateState(state); err != nil {
753			return fmt.Errorf("refusing to persist invalid state: %w", err)
754		}
755		payload, err := json.MarshalIndent(state, "", "  ")
756		if err != nil {
757			return err
758		}
759		payload = append(payload, '\n')
760	
761		dir := filepath.Dir(s.path)
762		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
763		if err != nil {
764			return err
765		}
766		tmpName := tmp.Name()
767		cleanup := func() { _ = os.Remove(tmpName) }
768		if _, err := tmp.Write(payload); err != nil {
769			_ = tmp.Close()
770			cleanup()
771			return err
772		}
773		if err := tmp.Sync(); err != nil {
774			_ = tmp.Close()
775			cleanup()
776			return err
777		}
778		if err := tmp.Close(); err != nil {
779			cleanup()
780			return err
781		}
782		if err := os.Chmod(tmpName, 0o600); err != nil {
783			cleanup()
784			return err
785		}
786		if err := os.Rename(tmpName, s.path); err != nil {
787			cleanup()
788			return err
789		}
790		if err := syncDir(dir); err != nil {
791			return err
792		}
793		return nil
794	}
795	
796	func syncDir(dir string) error {
797		d, err := os.Open(dir)
798		if err != nil {
799			return err
800		}
801		defer d.Close()
802		return d.Sync()
803	}
