61	func usage() {
62		fmt.Println(`usage: govflow <command> [flags]
63	
64	legacy commands:
65	  demo                         run the built-in voting demo
66	  version                      print the version
67	
68	local treasury commands:
69	  init       --state FILE --balance N
70	             create a new state file with the initial treasury balance
71	  register   --state FILE --id ID --timelock N --action A [--action A ...]
72	             register a passed proposal (idempotent; conflicting content errors)
73	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
74	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
75	             --timelock N [--action A ...]
76	             create a voting proposal with roster, weights, delegations and a
77	             voting window (idempotent on identical content; conflict otherwise)
78	  vote       --state FILE --id ID --voter M --choice for|against --now N
79	             cast one ballot as a final representative (repeat same choice is
80	             idempotent; changing choice errors)
81	  tally      --state FILE --id ID --now N
82	             tally a proposal at/after its deadline; repeat calls return the
83	             first result
84	  execute    --state FILE --id ID --now N
85	             execute a passed proposal whose timelock has elapsed
86	             (works for both registered and voted proposals)
87	  balances   --state FILE [--account ACCT]
88	             show treasury and recipient account balances
89	  proposal   --state FILE --id ID
90	             show one registered proposal
91	  proposals  --state FILE
92	             list all registered proposals by id
93	  receipt    --state FILE --id ID
94	             show the execution receipt of one proposal
95	  receipts   --state FILE
96	             list all receipts in the order they were successfully committed
97	
98	all treasury commands accept --json for machine-readable output.`)
99	}
100	
101	// fail prints a domain error to stderr and exits 1; usage errors exit 2.
102	func fail(err error) {
103		fmt.Fprintf(os.Stderr, "error: %v\n", err)
104		os.Exit(1)
105	}
106	
107	type commonFlags struct {
108		state  string
109		asJSON bool
110		fs     *flag.FlagSet
111	}
112	
113	func newCmdFlags(name string) *commonFlags {
114		fs := flag.NewFlagSet(name, flag.ContinueOnError)
115		fs.SetOutput(io.Discard)
116		cf := &commonFlags{fs: fs}
117		fs.StringVar(&cf.state, "state", "", "path to the local treasury state file")
118		fs.BoolVar(&cf.asJSON, "json", false, "emit machine-readable JSON")
119		return cf
120	}
121	
122	func (c *commonFlags) parse(args []string) {
123		if err := c.fs.Parse(args); err != nil {
124			fmt.Fprintf(os.Stderr, "usage error: %v\n", err)
125			c.fs.SetOutput(os.Stderr)
126			c.fs.Usage()
127			os.Exit(2)
128		}
129		if c.state == "" {
130			fmt.Fprintf(os.Stderr, "usage error: --state is required\n")
131			os.Exit(2)
132		}
133	}
134	
135	func emitJSON(v any) {
136		raw, err := json.MarshalIndent(v, "", "  ")
137		if err != nil {
138			fail(err)
139		}
140		fmt.Println(string(raw))
141	}
142	
143	func parseIntFlag(fs *flag.FlagSet, name, raw string) int64 {
144		if raw == "" {
145			fmt.Fprintf(os.Stderr, "usage error: --%s is required\n", name)
146			os.Exit(2)
147		}
148		value, err := strconv.ParseInt(raw, 10, 64)
149		if err != nil {
150			fmt.Fprintf(os.Stderr, "usage error: --%s must be an int64: %v\n", name, err)
151			os.Exit(2)
152		}
153		return value
154	}
155	
156	// actionList 收集重复出现的 --action 参数，保持登记顺序。
157	type actionList []string
158	
159	func (a *actionList) String() string { return fmt.Sprint([]string(*a)) }
160	func (a *actionList) Set(v string) error {
161		*a = append(*a, v)
162		return nil
163	}
164	
165	func runInit(args []string) {
166		cf := newCmdFlags("init")
167		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
168		cf.parse(args)
169		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
170	
171		store, err := govflow.InitTreasury(cf.state, balance)
172		if err != nil {
173			fail(err)
174		}
175		defer store.Close()
176		if cf.asJSON {
177			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
178			return
179		}
180		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
181	}
182	
183	func runRegister(args []string) {
184		cf := newCmdFlags("register")
185		id := cf.fs.String("id", "", "proposal id (non-empty)")
186		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
187		var actions actionList
