36		cmd.Stdout = &so
37		cmd.Stderr = &se
38		err := cmd.Run()
39		if ee, ok := err.(*exec.ExitError); ok {
40			code = ee.ExitCode()
41		} else if err != nil {
42			t.Fatalf("run cli %v: %v", args, err)
43		}
