160	// TestCrossProcessCrashConsistency：在并发执行期间反复 SIGKILL 进程，
161	// 状态文件在任何时刻都只能是整项执行前或执行后的完整状态。
162	func TestCrossProcessCrashConsistency(t *testing.T) {
163		binary := buildCLI(t)
164		state := filepath.Join(t.TempDir(), "treasury.json")
165		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000000"); code != 0 {
166			t.Fatal("init failed")
167		}
168		const n = 200
169		for i := 0; i < n; i++ {
170			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
171				"--timelock", "0", "--action", "transfer:a:1"); code != 0 {
172				t.Fatalf("register %d failed", i)
173			}
174		}
175	
176		// 启动后立刻 SIGKILL：杀死可能落在执行前、写盘前后任意位置。
177		var wg sync.WaitGroup
178		for i := 0; i < n; i++ {
179			wg.Add(1)
180			go func(i int) {
181				defer wg.Done()
182				cmd := exec.Command(binary, "execute", "--state", state, "--id", "gip-"+itoa(i), "--now", "0")
183				if err := cmd.Start(); err != nil {
184					t.Errorf("start %d: %v", i, err)
185					return
186				}
187				if i%3 == 0 {
188					_ = cmd.Process.Kill()
189				}
190				_ = cmd.Wait()
191			}(i)
192		}
193		wg.Wait()
194	
195		// 最终状态必须能严格打开：余额与凭据重放一致；被杀死的执行要么整体发生、要么整体未发生。
196		store, err := Open(state)
197		if err != nil {
198			t.Fatalf("state after crashes is unusable: %v", err)
199		}
200		defer store.Close()
201		treasury, err := store.TreasuryBalance()
202		if err != nil {
203			t.Fatal(err)
204		}
205		receipts, err := store.Receipts()
206		if err != nil {
207			t.Fatal(err)
208		}
209		if int64(len(receipts)) != 1000000-treasury {
210			t.Fatalf("invariant broken: receipts=%d treasury=%d", len(receipts), treasury)
211		}
212		// 每个 executed 提案恰好有凭据；无凭据的提案仍是 passed 且余额未变（重放校验已在 Open 中完成）。
213		executed := map[string]bool{}
214		for _, r := range receipts {
215			if executed[r.ProposalID] {
216				t.Fatalf("duplicate receipt for %s", r.ProposalID)
217			}
218			executed[r.ProposalID] = true
219		}
220		proposals, err := store.Proposals()
221		if err != nil {
222			t.Fatal(err)
223		}
224		for _, p := range proposals {
225			if p.State == "executed" && !executed[p.ID] {
226				t.Fatalf("proposal %s executed without receipt", p.ID)
227			}
228			if p.State == "passed" && executed[p.ID] {
229				t.Fatalf("proposal %s passed but has receipt", p.ID)
230			}
231		}
232	}
