355			"--member", "a:600", "--member", "b:400",
356			"--quorum", "600", "--start", "0", "--deadline", "10", "--timelock", "10",
357			"--action", "transfer:x:1"); code != 0 {
358			t.Fatal("create failed")
359		}
360		if _, _, code := runCLI(t, binary, state, "vote", "--id", "gip-c",
361			"--voter", "a", "--choice", "for", "--now", "5"); code != 0 {
362			t.Fatal("vote failed")
363		}
364		const n = 16
365		var wg sync.WaitGroup
366		start := make(chan struct{})
367		outputs := make([]string, n)
368		for i := 0; i < n; i++ {
369			wg.Add(1)
370			go func(i int) {
371				defer wg.Done()
372				<-start
373				so, _, _ := runCLI(t, binary, state, "tally", "--id", "gip-c",
374					"--now", strconv.Itoa(10+i), "--json")
375				outputs[i] = so
376			}(i)
377		}
378		close(start)
379		wg.Wait()
380		// 首个抢到锁的进程完成首次计票（其 now 未必最小）；其余进程必须拿到同一结论。
381		var winner string
382		for i, out := range outputs {
383			if !strings.Contains(out, `"passed": true`) {
384				t.Fatalf("tally %d diverged or failed: %s", i, out)
385			}
386			m := tallyTimeRe.FindStringSubmatch(out)
387			if m == nil {
388				t.Fatalf("tally %d missing tallied_at: %s", i, out)
389			}
390			if winner == "" {
391				winner = m[1]
392			} else if m[1] != winner {
393				t.Fatalf("tally %d tallied_at=%s, want first result %s", i, m[1], winner)
394			}
395		}
396		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-c", "--json")
397		if strings.Count(so, `"voted_at"`) != 1 {
398			t.Fatalf("ballot records changed under concurrent tally:\n%s", so)
399		}
